ation visualizes the propensity score distribution and the distribution of the AIPW estimates using grayscale plots, and it displays the predicted counterfactual outcomes by Family Income, providing comprehensive diagnostics and insights into the quality of the weighting and the balance achieved. Now, let’s show and discuss the comparison and bootstrapped standard deviations of these methods in a simple simulation, demonstrating that while the naive estimator is biased, the IPW estimator is unbiased with higher variance, and the AIPW estimator is unbiased with lower variance. set.seed(42) n_sim &lt;- 100 n &lt;- 1000 k &lt;- 5 results &lt;- data.frame( ate_true = rep(2, n_sim), ate_naive = numeric(n_sim), ate_ipw = numeric(n_sim), ate_aipw = numeric(n_sim) ) for (sim in 1:n_sim) { X1 &lt;- rnorm(n, mean = 0, sd = 1) X2 &lt;- rnorm(n, mean = 0, sd = 1) propensity &lt;- 1 / (1 + exp(-(0.5 + 0.3 * X1 - 0.2 * X2))) D &lt;- rbinom(n, 1, propensity) #Treatment assignment epsilon &lt;- rnorm(n, mean = 0, sd = 1) Y &lt;- 10 + 2 * D + 0.5 * X1 + 0.5 * X2 + epsilon # Outcome model data &lt;- data.frame(Y, D, X1, X2) # Naive estimate mean_Y_treated &lt;- mean(data$Y[data$D == 1]) mean_Y_control &lt;- mean(data$Y[data$D == 0]) ate_naive &lt;- mean_Y_treated - mean_Y_control # Estimate propensity score on entire data for IPW propensity_model &lt;- glm(D ~ X1 + X2, data = data, family = binomial) propensity_hat &lt;- predict(propensity_model, type = &quot;response&quot;) # IPW estimates treated_weights &lt;- data$D / propensity_hat mu1_ipw &lt;- sum(data$Y[data$D == 1] * treated_weights[data$D == 1]) / sum(treated_weights[data$D == 1]) control_weights &lt;- (1 - data$D) / (1 - propensity_hat) mu0_ipw &lt;- sum(data$Y[data$D == 0] * control_weights[data$D == 0]) / sum(control_weights[data$D == 0]) ate_ipw &lt;- mu1_ipw - mu0_ipw # Cross-fitting for AIPW folds &lt;- cut(1:n, breaks = k, labels = FALSE) ate_aipw_folds &lt;- numeric(k) for (fold in 1:k) { data_train &lt;- data[folds != fold, ] data_test &lt;- data[folds == fold, ] # Estimate propensity score on train data propensity_model_train &lt;- glm(D ~ X1 + X2, data = data_train, family = binomial) propensity_hat_test &lt;- predict(propensity_model_train, newdata = data_test, type = &quot;response&quot;) # Estimate outcome model on train data outcome_model_train &lt;- lm(Y ~ D + X1 + X2, data = data_train) # Create new data sets for potential outcomes for test data newdata_treated &lt;- data_test newdata_treated$D &lt;- 1 mu1_hat_test &lt;- predict(outcome_model_train, newdata = newdata_treated) newdata_control &lt;- data_test newdata_control$D &lt;- 0 mu0_hat_test &lt;- predict(outcome_model_train, newdata = newdata_control) # Compute AIPW estimates for test data term1_aipw1 &lt;- (data_test$D / propensity_hat_test) * (data_test$Y - mu1_hat_test) + mu1_hat_test mu1_aipw_test &lt;- mean(term1_aipw1) term1_aipw0 &lt;- ((1 - data_test$D) / (1 - propensity_hat_test)) * (data_test$Y - mu0_hat_test) + mu0_hat_test mu0_aipw_test &lt;- mean(term1_aipw0) ate_aipw_test &lt;- mu1_aipw_test - mu0_aipw_test ate_aipw_folds[fold] &lt;- ate_aipw_test } # Average AIPW estimate across folds mean_ate_aipw &lt;- mean(ate_aipw_folds) # Store results results$ate_naive[sim] &lt;- ate_naive results$ate_ipw[sim] &lt;- ate_ipw results$ate_aipw[sim] &lt;- mean_ate_aipw } # Summarize results mean_naive &lt;- mean(results$ate_naive) sd_naive &lt;- sd(results$ate_naive) mean_ipw &lt;- mean(results$ate_ipw) sd_ipw &lt;- sd(results$ate_ipw) mean_aipw &lt;- mean(results$ate_aipw) sd_aipw &lt;- sd(results$ate_aipw) cat(&quot;Naive estimate: mean =&quot;, mean_naive, &quot;, sd =&quot;, sd_naive, &quot;
