2.697100 -3.4509000 15.49413 -8.524767 -12.633133 2.173933 -3.292467 ## 5 -13.800000 -0.7464333 16.56037 -11.723300 -7.062600 -13.184300 2.813033 ## 6 -11.665500 1.9710333 20.05657 -10.684600 3.292100 -9.363967 6.406867 ## 7 -9.373733 -5.8512667 23.13793 -17.310433 6.720633 -16.444167 11.981633 ## 8 -10.233033 -12.3322000 22.61410 -9.796867 5.102200 -14.007967 12.177500 ## 9 -12.145600 -22.5280667 45.52763 -22.078400 7.680600 -21.096567 8.656400 ## 10 -11.179767 -19.4309000 47.87777 -23.726333 8.190267 -22.027567 12.756467 ## 11 -8.145300 -18.9786333 49.77097 -26.724600 14.152900 -21.407233 11.465667 ## 12 -10.947600 -18.4935667 47.21440 -23.789367 9.581900 -19.870133 8.059733 ## 13 -9.108533 -16.9865000 40.43617 -22.952300 9.804567 -19.631100 10.097000 ## 14 -10.174000 -20.3914333 43.31103 -26.960767 12.482533 -19.625367 5.761600 actual &lt;- test[, 1] rmspe &lt;- c() for (i in 1:nrow(fh)) { rmspe[i] &lt;- sqrt(mean((fh[i, ] - actual) ^ 2)) } rmspe ## [1] 42.25558 41.30589 38.97195 40.04286 40.51307 43.67209 44.61230 44.66197 ## [9] 44.42342 43.71028 42.97556 42.68597 which.min(rmspe) ## [1] 3 plot( actual, type = &quot;l&quot;, col = &quot;red&quot;, ylim = c(-80,+50), ylab = &quot;Actual (red) vs. Forecasts&quot;, xlab = &quot;Last 7 days&quot;, main = &quot;7-Day Foerecasts&quot;, lwd = 3 ) lines(fh[1,], type = &quot;l&quot;, col = &quot;steelblue&quot;) lines(fh[3,], type = &quot;l&quot;, col = &quot;seagreen&quot;) lines(fh[5,], type = &quot;l&quot;, col = &quot;darkorange&quot;) lines(fh[12,], type = &quot;l&quot;, col = &quot;black&quot;) legend( &quot;bottomright&quot;, title = &quot;Lags&quot;, legend = c(&quot;3-day&quot;, &quot;5-day&quot;, &quot;7-day&quot;, &quot;14-day&quot;), col = c(&quot;steelblue&quot;, &quot;seagreen&quot;, &quot;darkorange&quot;, &quot;black&quot;), lty = c(1, 1, 1, 1, 1), bty = &quot;o&quot;, cex = 0.75 ) It seems that additional predictors do increase the accuracy. Again, relative to the best model (5-day window) our 7-day window correctly captures most ups and downs in the forecast. Now, a visual inspection shows that all RMSPE’s are lower than the univariate forecasts. We would conclude that this is because of the new predictors, specially mobility, temperature, and humidity. As a side note, we need to test if those differences are statistical significant or not (i.e. Diebold-Mariano Test). 29.5 Rolling and expanding windows A seven-day window is not enough for a reliable judgment on the forecast accuracy. One way to deal with this issue is to use rolling or expanding windows to predict the next h days. The following example shows a 1-day-ahead forecast with varying lags for embedding. library(randomForest) l = 3:10 # lags for embedding ws = 150 # size of each rolling window rmspe &lt;- c() all_fh &lt;- vector(mode = &quot;list&quot;, length = length(l)) all_y &lt;- vector(mode = &quot;list&quot;, length = length(l)) for (s in 1:length(l)) { dt &lt;- as.data.frame(embed(as.matrix(dft[,-1]), l[s])) nwin &lt;- nrow(dt) - ws #number of windows fh &lt;- c() y &lt;- c() for (i in 1:nwin) { train &lt;- dt[i:(ws + i - 1),] # each loop, window moves one day forward test &lt;- dt[(ws + i),] set.seed(i + s) fit &lt;- randomForest(train[,-1], train[, 1]) fh[i] &lt;- predict(fit, test[,-1]) y[i] &lt;- test[, 1] # to use later for plotting } all_y[[s]] &lt;- y all_fh[[s]] &lt;- fh err &lt;- test[, 1] - fh rmspe[s] &lt;- sqrt(mean(err ^ 2)) } rmspe ## [1] 45.00315 45.02472 45.31378 44.83595 45.81351 47.01531 47.14842 46.94298 bst &lt;- which.min(rmspe) l[bst] # Winning lag in embedding ## [1] 6 To adjust the application above to an expanding-window forecast, we just need to change dt[i:(ws + i - 1), ] to dt[1:(ws + i - 1), ] in the script. Now, we can plot the results: par(mfrow = c(1, 2)) plot( all_y[[bst]], type = &quot;l&quot;, col = &quot;orangered&quot;, ylab = &quot;Actual (red) vs Predicted (Blue)&quot;, xlab = &quot;Days&quot;, main = &quot;1-Day-Ahead&quot; ) lines(all_fh[[bst]], col = &quot;royalblue&quot;) plot( all_y[[bst]][60:110], type = &quot;o&quot;, col = &quot;orangered&quot;, ylab = &quot;Actual (red) vs Predicted (Blue)&quot;, xlab = &quot;Days&quot;, main = &quot;Last 50 Days&quot; ) lines(all_fh[[bst]][60:110], col = &quot;royalblue&quot;) Getting the predicted values back to originals can be achieved by: \[  egin{aligned} &amp; y_{t+1}=y_t+z_{t+1} \ &amp; y_{t+2}=y_{t+1}+z_{t+2}=y_t+z_{t+1}+z_{t+2} \end{aligned} \] set.seed(321) y &lt;- rnorm(10) z &lt;- diff(y) # first differences back &lt;- cumsum(c(y[1], z)) cbind(y, back) ## y back ## [1,] 1.7049032 1.7049032 ## [2,] -0.7120386 -0.7120386 ## [3,] -0.2779849 -0.2779849 ## [4,] -0.1196490 -0.1196490 ## [5,] -0.1239606 -0.1239606 ## [6,] 0.2681838 0.2681838 ## [7,] 0.7268415 0.7268415 ## [8,] 0.2331354 0.2331354 ## [9,] 0.3391139 0.3391139 ## [10,] -0.5519147 -0.5519147 Since our algorithm predict the changes in observations, a simple sum would do the job for back transformation. For example, as a starting point, our algorithm predicts the change in \(Y\) from day 156 to 157 (window size 150 plus the best lag window, 6). When we add this predicted change to the actual \(Y\) at 156, it will give us the back-transformed forecast at day 157. y &lt;- df$cases # The first forecast is at ws (150) + l[best] (6) + 1, which is 157 # The first actual Y should start a day earlier # removing all Y&#39;s until ws+l[bst] y_a_day_before &lt;- y[-c(1:(ws + l[bst] - 1))] # This adds predicted changes to observed values a day earlier back_forecast &lt;- head(y_a_day_before,-1) + all_fh[[bst]] # Actual Y&#39;s in the test set starting at ws (150) + l[best] (6) + 1, which is 157 ytest &lt;- y[-c(1:(ws + l[bst]))] plot( ytest, type = &quot;l&quot;, col = &quot;royalblue&quot;, ylab = &quot;Actual Y (Blue) vs Forecast (Red)&quot;, xlab = &quot;Days&quot;, main = &quot;Back-transformed Forecast&quot; ) lines(back_forecast, type = &quot;l&quot;, col = &quot;orangered&quot;) It seems that, for most days, our algorithm simply forecasts the next day by using the value from the day before. If we change our algorithm to a 7-day-ahead forecast, this would be different. This is also a common problem when the predictive model has a poor forecasting power. Again, this is not due to our algorithm, but forecasting an epi curve with imperfect test data is almost impossible job, as we highlighted earlier. In practice, however, there are several ways that we can improve the scripts above. For example, we can consider the (rolling or expanding) window size as a hyperparameter. We can also have an explicit training for the Random Forest algorithm. We can have an ensemble forecasting by adding other predictive algorithms to the script, like boosting. Further, we can develop a base forecast that would give us a benchmark to see how much our algorithm improves against that base. Lastly, we could apply a transformation to the data in order to stabilize the variance in all variables. https://data.ontario.ca/en/dataset?groups=2019-novel-coronavirus#byPHU↩︎
